    .animate-pulse-dot {
      animation: pulse-dot 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
    }

    /* Brand Logo Shadow & Harmony Styles */
    .brand-logo-img {
      transition: filter 0.3s ease, transform 0.25s ease;
      filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.12)) drop-shadow(0 1px 2px rgba(0, 0, 0, 0.08));
    }
    html:not(.dark) .brand-logo-img {
      mix-blend-mode: multiply;
    }
    .dark .brand-logo-img {
      filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.65)) drop-shadow(0 0 16px rgba(227, 34, 39, 0.3));
    }
    .brand-logo-img:hover {
      transform: translateY(-1px) scale(1.02);
    }
    .dark .brand-logo-img:hover {
      filter: drop-shadow(0 6px 14px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 22px rgba(227, 34, 39, 0.45));
    }
  </style>
</head>
