  <script>
    /* Auto-transparent canvas processor for logo in dark mode */
    function makeLogoTransparent(img) {
      if (!img || img.dataset.processed === "true") return;
      img.dataset.processed = "true";
      img.onload = null; // Prevent re-triggering onload loop
      try {
        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth || img.width;
        canvas.height = img.naturalHeight || img.height;
        if (!canvas.width || !canvas.height) return;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const d = imgData.data;
        let hasWhite = false;
        for (let i = 0; i < d.length; i += 4) {
          // If pixel is near pure white, turn alpha to 0 (transparent)
          if (d[i] > 235 && d[i+1] > 235 && d[i+2] > 235) {
            d[i+3] = 0;
            hasWhite = true;
          }
        }
        if (hasWhite) {
          ctx.putImageData(imgData, 0, 0);
          img.src = canvas.toDataURL('image/png');
        }
      } catch (err) {
        // Fallback gracefully (e.g. if local file canvas security policy blocks getImageData)
      }
