    function toggleDarkMode() {
      const htmlEl = document.documentElement;
      const isDark = htmlEl.classList.toggle("dark");

      const sunIcon = document.getElementById("sunIcon");
      const moonIcon = document.getElementById("moonIcon");

      if (isDark) {
        sunIcon.classList.add("hidden");
        moonIcon.classList.remove("hidden");
      } else {
        sunIcon.classList.remove("hidden");
        moonIcon.classList.add("hidden");
      }

      // Update charts theme
      updateChartsTheme(isDark ? 'dark' : 'light');
    }

    function updateChartsTheme(themeMode) {
      const chartTextColor = themeMode === 'dark' ? '#a1a1a6' : '#6e6e73';
      const chartGridColor = themeMode === 'dark' ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.06)';

      const macroChartKeys = ['macroGdp', 'macroInterest', 'macroUsdVnd', 'macroGold', 'macroOil'];
