"    // Intercept Paste in the Rich Editor (Images & Text)
    function handleEditorPaste(e) {
      const clipboardData = e.clipboardData || window.clipboardData;
      if (!clipboardData) return;

      // 1. Image Paste from Clipboard (Screenshots, copied images)
      const items = clipboardData.items;
      if (items) {
        for (let i = 0; i < items.length; i++) {
          if (items[i].type && items[i].type.startsWith("image/")) {
            e.preventDefault();
            const file = items[i].getAsFile();
            if (file) {
              const reader = new FileReader();
              reader.onload = function(evt) {
                insertInlineImageToEditor(evt.target.result, file.name || "Biểu đồ dán từ Clipboard");
              };
              reader.readAsDataURL(file);
            }
            return;
          }
        }
      }

      // 2. Text / HTML Paste: Strip foreign backgrounds, styles, and format according to system
      e.preventDefault();

      const rawHtml = clipboardData.getData('text/html');
      const plainText = clipboardData.getData('text/plain');

      if (rawHtml) {
        const cleanHtml = sanitizePastedContent(rawHtml);
        if (cleanHtml && cleanHtml.trim()) {
          document.execCommand('insertHTML', false, cleanHtml);
          return;
        }
      }

      if (plainText) {
        const lines = plainText.split(/\r?\n/);
        const pWrapped = lines.map(line => {
          const trimmed = line.trim();
          if (!trimmed) return '<p><br></p>';
          return `<p>${escapeHtml(line)}</p>`;
        }).join('');
        document.execCommand('insertHTML', false, pWrapped);
      }
    }"

