        StockApp.buyCriteria.filterMaAndBase = true;
        StockApp.buyCriteria.filterLowestPeTop10 = true;
      } else if (mode === 'ma_base') {
        StockApp.buyCriteria.filterMaAndBase = true;
        StockApp.buyCriteria.filterLowestPeTop10 = false;
      } else if (mode === 'lowest_pe') {
        StockApp.buyCriteria.filterMaAndBase = false;
        StockApp.buyCriteria.filterLowestPeTop10 = true;
      } else if (mode === 'all') {
        StockApp.buyCriteria.filterMaAndBase = false;
        StockApp.buyCriteria.filterLowestPeTop10 = false;
      }

      updateBuyFilterUI();
      renderScreenerTable();
