      if (critKey === 'ma_base') {
        StockApp.buyCriteria.filterMaAndBase = !StockApp.buyCriteria.filterMaAndBase;
      } else if (critKey === 'lowest_pe') {
        StockApp.buyCriteria.filterLowestPeTop10 = !StockApp.buyCriteria.filterLowestPeTop10;
      }

