    """Tự động chọn cổng khả dụng cho Dashboard và API"""
    global HOST, PORT
    candidate_ports = [PORT, 8088, 8899, 8080, 5050, 3000, 8000] if PORT != 8088 else [8088, 8899, 8080, 5050, 3000, 8000]
    candidate_hosts = ["0.0.0.0", "127.0.0.1"]

    server = None
    selected_host = HOST
    selected_port = PORT

