            continue
        for h in candidate_hosts:
            try:
                server = ThreadedHTTPServer((h, p), StockDataHandler)
                selected_host = h
                selected_port = p
                break
            except (PermissionError, OSError):
                continue
        if server:
            break

    if not server:
        try:
            server = ThreadedHTTPServer(("127.0.0.1", 0), StockDataHandler)
            selected_host = "127.0.0.1"
