"const https = require('https');

async function getIndexLive(symbol) {
  const now = Math.floor(Date.now() / 1000);
  const from = now - (3600 * 2); // last 2h
  const url = `https://services.entrade.com.vn/chart-api/v2/ohlcs/index?resolution=1&symbol=${symbol}&from=${from}&to=${now}`;

  return new Promise((resolve) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          const len = json.c ? json.c.length : 0;
          if (len > 0) {
            resolve({ symbol, price: json.c[len - 1] });
          } else {
            resolve({ symbol, error: 'no data' });
          }
        } catch (e) {
          resolve({ symbol, error: e.message });
        }
      });
    }).on('error', err => resolve({ symbol, error: err.message }));
  });
}

async function checkAll() {
  const symbols = ['VNINDEX', 'VN30', 'HNX', 'UPCOM'];
  for (const s of symbols) {
    const res = await getIndexLive(s);
    console.log(s, ':', res);
  }
}
checkAll();
"

