"node -e "
const https = require('https');
function fetchJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', () => {
        try { resolve(JSON.parse(raw)); } catch(e) { reject(e); }
      });
    }).on('error', reject);
  });
}

async function run() {
  const t0 = Date.now();
  const exchanges = ['hose', 'hnx', 'upcom'];
  const results = await Promise.allSettled(exchanges.map(ex => fetchJson('https://iboard-query.ssi.com.vn/stock/exchange/' + ex)));
  const breadth = {};
  const total = { adv: 0, ref: 0, dec: 0, ceil: 0, flr: 0 };

  exchanges.forEach((ex, idx) => {
    const res = results[idx];
    let adv = 0, ref = 0, dec = 0, ceil = 0, flr = 0;
    if (res.status === 'fulfilled' && res.value && Array.isArray(res.value.data)) {
      res.value.data.forEach(it => {
        const sym = it.stockSymbol || '';
        if (sym.length > 4) return;
        const mp = it.matchedPrice || 0;
        const rp = it.refPrice || 0;
        const cp = it.ceiling || 0;
        const fp = it.floor || 0;
        const chg = it.priceChange || 0;

        if (chg > 0 || (mp > rp && rp > 0)) {
          adv++;
          if (cp > 0 && mp >= cp) ceil++;
        } else if (chg < 0 || (mp < rp && mp > 0 && rp > 0)) {
          dec++;
          if (fp > 0 && mp <= fp) flr++;
        } else {
          ref++;
        }
      });
    }
    breadth[ex] = { adv, ref, dec, ceil, flr };
    total.adv += adv;
    total.ref += ref;
    total.dec += dec;
    total.ceil += ceil;
    total.flr += flr;
  });
  console.log('TIME:', Date.now() - t0, 'ms');
  console.log('TOTAL:', total);
  console.log('HOSE:', breadth.hose);
  console.log('HNX:', breadth.hnx);
  console.log('UPCOM:', breadth.upcom);
}
run();
""

