"const https = require('https');

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', () => resolve(raw));
    }).on('error', reject);
  });
}

async function main() {
  const html = await get('https://iboard.ssi.com.vn');
  const matches = html.match(/src="([^"]+\.js)"/g) || [];
  console.log('Found scripts:', matches);
  for (const m of matches) {
    const src = m.replace('src="', '').replace('"', '');
    const full = src.startsWith('http') ? src : 'https://iboard.ssi.com.vn' + src;
    console.log('Checking:', full);
    const code = await get(full);
    const indexMatches = code.match(/https?:\/\/[^"'\s]+index[^"'\s]*/gi) || [];
    if (indexMatches.length > 0) {
      console.log('Matches in', full, indexMatches.slice(0, 5));
    }
    const apiMatches = code.match(/\/stock\/[a-zA-Z0-9_\-\/]+/g) || [];
    const uniqueApis = [...new Set(apiMatches)];
    console.log('APIs in', full, uniqueApis.filter(a => a.includes('index') || a.includes('market')));
  }
}

main().catch(console.error);
"

