"const https = require('https');
const zlib = require('zlib');

https.get('https://trading.vietcap.com.vn/api/market/indices', { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
  console.log('STATUS:', res.statusCode);
  console.log('CORS:', res.headers['access-control-allow-origin']);
  console.log('Encoding:', res.headers['content-encoding']);

  const chunks = [];
  res.on('data', c => chunks.push(c));
  res.on('end', () => {
    const buffer = Buffer.concat(chunks);
    zlib.gunzip(buffer, (err, decoded) => {
      const text = err ? buffer.toString() : decoded.toString();
      try {
        const json = JSON.parse(text);
        console.log('SUCCESS JSON! Count:', Array.isArray(json) ? json.length : Object.keys(json));
        console.log('Sample:', JSON.stringify(json, null, 2).slice(0, 500));
      } catch (e) {
        console.log('Raw text:', text.slice(0, 300));
      }
    });
  });
});
"

