"const https = require('https');

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', () => {
        try { resolve(JSON.parse(raw)); } catch(e) { reject(e); }
      });
    }).on('error', reject);
  });
}

async function testFullLiveSync() {
  const t0 = Date.now();
  const now = Math.floor(Date.now() / 1000);
  const from = now - 3600;

  // 1. Fetch indices
  const [vnindexRes, vn30Res, hnxRes] = await Promise.allSettled([
    fetchJson(`https://iboard-api.ssi.com.vn/statistics/charts/history?symbol=VNINDEX&resolution=1&from=${from}&to=${now}`),
    fetchJson(`https://iboard-api.ssi.com.vn/statistics/charts/history?symbol=VN30&resolution=1&from=${from}&to=${now}`),
