"async function getACB() {
  const from = Math.floor(new Date('2025-01-01').getTime() / 1000);
  const to = Math.floor(Date.now() / 1000);
  const res = await fetch('https://iboard-api.ssi.com.vn/statistics/charts/history?symbol=ACB&resolution=D&from=' + from + '&to=' + to);
  const json = await res.json();
  const c = json.data.c;
  const t = json.data.t;

  console.log('10 phiên giao dịch gần nhất của ACB:');
  const last10Closes = c.slice(-10);
  const last10Times = t.slice(-10);
  last10Times.forEach((ts, idx) => {
    const d = new Date(ts * 1000);
    const dateStr = d.toLocaleDateString('vi-VN');
    console.log(`Phiên ${idx + 1} (${dateStr}): ${(last10Closes[idx] * 1000).toLocaleString('vi-VN')} đ`);
  });

  const ma10 = last10Closes.reduce((a, b) => a + b, 0) / 10;
  const ma50 = c.slice(-50).reduce((a, b) => a + b, 0) / 50;
  const lastClose = c[c.length - 1];

  console.log('\n--- KẾT QUẢ TÍNH TOÁN MA ---');
  console.log('Giá đóng cửa phiên gần nhất:', (lastClose * 1000).toLocaleString('vi-VN') + ' đ');
  console.log('Đường MA10 (10 phiên):', (ma10 * 1000).toLocaleString('vi-VN') + ' đ');
  console.log('Đường MA50 (50 phiên):', (ma50 * 1000).toLocaleString('vi-VN') + ' đ');
  console.log('Chênh lệch so với MA10:', (((lastClose - ma10) / ma10) * 100).toFixed(2) + '%');
  console.log('Chênh lệch so với MA50:', (((lastClose - ma50) / ma50) * 100).toFixed(2) + '%');
  console.log('Giá có nằm trên cả 2 đường MA10 & MA50 không?:', (lastClose > ma10 && lastClose > ma50) ? 'ĐẠT' : 'KHÔNG ĐẠT');
}
getACB();
"

