"node -e "
const https = require('https');

function getYahooQuote(symbol) {
  const url = 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(symbol) + '?interval=1d&range=2d';
  return new Promise((resolve) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' }, timeout: 8000 }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          const meta = json.chart.result[0].meta;
          const currentPrice = meta.regularMarketPrice;
          const prevClose = meta.chartPreviousClose || meta.previousClose;
          const diff = currentPrice - prevClose;
          const pct = (diff / prevClose) * 100;
          resolve({
            symbol,
            price: currentPrice,
            prevClose,
            diff: parseFloat(diff.toFixed(2)),
            pct: parseFloat(pct.toFixed(2))
          });
        } catch(e) {
          resolve({ symbol, error: e.message });
        }
      });
    }).on('error', e => resolve({ symbol, error: e.message }));
  });
}

(async () => {
  const symbols = [
    '^DJI',      // Dow Jones
    '^GSPC',     // S&P 500
    '^IXIC',     // Nasdaq
    '^N225',     // Nikkei 225
    '000001.SS', // Shanghai
    '^KS11',     // Kospi
    '^HSI',      // Hang Seng
    'GC=F',      // Vàng thế giới
    'BZ=F',      // Dầu Brent
    'CL=F',      // Dầu WTI
    'DX-Y.NYB'   // DXY
  ];

  for (const s of symbols) {
    const res = await getYahooQuote(s);
    console.log(res);
  }
})();
""

