  const lines = fs.readFileSync(transcriptFile, 'utf-8').trim().split('\n');
  const summary = [
    '# 💬 LỊCH SỬ HỘI THOẠI & YÊU CẦU DỰ ÁN (VIETCAPLINK STOCK)',
