"const fs = require('fs');
const content = fs.readFileSync('index.html', 'utf8');

// Parse stock objects from index.html
const startIdx = content.indexOf('stocks: [');
const endIdx = content.indexOf('portfolio: [');
const sub = content.substring(startIdx, endIdx);

const regex = /"symbol":\s*"([^"]+)"[\s\S]*?"baseMonths":\s*([0-9.]+)[\s\S]*?"baseSessions":\s*([0-9.]+)[\s\S]*?"baseTightness":\s*([0-9.]+)[\s\S]*?"baseUpperHalf":\s*(true|false)[\s\S]*?"aboveMA10_50":\s*(true|false)/g;

let match;
const stocks = [];
while ((match = regex.exec(sub)) !== null) {
  stocks.push({
    symbol: match[1],
    baseMonths: parseFloat(match[2]),
    baseSessions: parseInt(match[3]),
    baseTightness: parseFloat(match[4]),
    baseUpperHalf: match[5] === 'true',
    aboveMA10_50: match[6] === 'true'
  });
}

console.log('Total parsed stocks:', stocks.length);

const c3_6 = stocks.filter(s => s.baseMonths >= 3.0 && s.baseMonths < 6.0);
const c6_12 = stocks.filter(s => s.baseMonths >= 6.0 && s.baseMonths <= 12.0);
const c12plus = stocks.filter(s => s.baseMonths > 12.0);

console.log('3-6M:', c3_6.length, c3_6.map(s => `${s.symbol} (${s.baseMonths}T, MA=${s.aboveMA10_50}, Upper=${s.baseUpperHalf})`));
console.log('6-12M:', c6_12.length, c6_12.map(s => `${s.symbol} (${s.baseMonths}T, MA=${s.aboveMA10_50}, Upper=${s.baseUpperHalf})`));
console.log('>12M:', c12plus.length, c12plus.map(s => `${s.symbol} (${s.baseMonths}T, MA=${s.aboveMA10_50}, Upper=${s.baseUpperHalf})`));
"

