function toggleBaseDurationTier(tier, event) {
      if (event && event.stopPropagation) {
        event.stopPropagation();
      }

      // If Card 1 was deselected (filterMaAndBase is false):
      // Clicking any duration tier turns on Card 1 with ONLY that tier!
      if (!StockApp.buyCriteria.filterMaAndBase) {
        StockApp.buyCriteria.filterMaAndBase = true;
        if (StockApp.buyCriteria.filterLowestPeTop10) {
          StockApp.buyCriteria.mode = 'both';
        } else {
          StockApp.buyCriteria.mode = 'ma_base';
        }
        StockApp.buyCriteria.baseDurationTiers = [tier];
        StockApp.buyCriteria.baseDurationTier = tier;
        clearDurationTierWarning();
        updateBuyFilterUI();
        renderScreenerTable();
        return;
      }

      let current = Array.isArray(StockApp.buyCriteria.baseDurationTiers)
        ? [...StockApp.buyCriteria.baseDurationTiers]
        : [];

      const isSelected = current.includes(tier);

      if (isSelected) {
        // User clicks an ALREADY SELECTED tier -> Untick it (Bỏ chọn)
        if (current.length === 1) {
          // Bỏ chọn ô duy nhất -> Hết mốc thời gian -> Tắt luôn Card 1
          StockApp.buyCriteria.baseDurationTiers = [];
          StockApp.buyCriteria.baseDurationTier = null;
          StockApp.buyCriteria.filterMaAndBase = false;
          if (StockApp.buyCriteria.filterLowestPeTop10) {
            StockApp.buyCriteria.mode = 'lowest_pe';
          } else {
            StockApp.buyCriteria.mode = 'all';
          }
          clearDurationTierWarning();
          updateBuyFilterUI();
          renderScreenerTable();
          return;
        }

        const next = current.filter(t => t !== tier);
        // Check forbidden gap: if next leaves 3_6m and 12m_plus without 6_12m
        if (next.includes('3_6m') && next.includes('12m_plus') && !next.includes('6_12m')) {
          showDurationTierWarning("⚠️ Không thể bỏ chọn ô 6 – 12 tháng khi cả 2 mốc 3 – 6 tháng và trên 12 tháng đang bật (khoảng thời gian nền phải liên tục).");
          return;
        }

        StockApp.buyCriteria.baseDurationTiers = next;
        StockApp.buyCriteria.baseDurationTier = next[0] || null;
        clearDurationTierWarning();
      } else {
        // User clicks an UNSELECTED tier -> Tick it (Chọn)
        const next = [...current, tier];
        // Check forbidden gap: if next contains 3_6m and 12m_plus without 6_12m
        if (next.includes('3_6m') && next.includes('12m_plus') && !next.includes('6_12m')) {
          showDurationTierWarning("⚠️ Khoảng thời gian nền phải liên tục. Vui lòng chọn thêm ô 6 – 12 tháng ở giữa (hoặc bỏ chọn ô hiện tại trước).");
          return;
        }

        StockApp.buyCriteria.baseDurationTiers = next;
        StockApp.buyCriteria.baseDurationTier = next[0] || tier;
        clearDurationTierWarning();
      }

      updateBuyFilterUI();
      renderScreenerTable();
    }

